int BinSearch (char *item,char *table[],int n, int (*Sosanh)(const char*,const char*)) {
int bot = 0, top = n - 1, mid, cmp;
while (bot < top) {
mid = (bot + top) / 2;
if ((cmp = Sosanh(item,table[mid])) == 0) return mid;
else if (cmp < 0) top = mid - 1;
else bot = mid + 1;
}
return -1;
}
